```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate
WHERE {
  VALUES ?film { dbr:A_Groom_from_the_Other_World dbr:Aniyara }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director }
  UNION
  { ?film dbo:director ?director }

  # death date of the director (prefer dbp:deathDate, fallback to dbo:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDate }
  OPTIONAL { ?director dbo:deathDate ?deathDate }
  FILTER (BOUND(?deathDate))
}
LIMIT 100
```

